export const previewHtml = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; form-action 'none'; base-uri 'none'\"><meta name=\"color-scheme\" content=\"dark\"><title>CMPRI — Employment Preview</title><style>\n:root{font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#f4f6fa;background:#101b2b;--yellow:#ffff00;color-scheme:dark}*{box-sizing:border-box}body{margin:0}header{border-bottom:3px solid var(--yellow);background:#0d192c}header>div{max-width:900px;margin:auto;display:flex;gap:14px;align-items:center;padding:17px 24px}img{width:46px;height:46px;border-radius:8px}.brand{font-size:19px;font-weight:700}.sub{margin-top:5px;color:#ced8e6}.badge{margin-left:auto;background:var(--yellow);color:#000;padding:6px 9px;border-radius:5px;font-size:10px;font-weight:bold;white-space:nowrap}main{max-width:900px;margin:25px auto;padding:0 24px 36px}h1{font-size:27px;margin:8px 0 12px}h2{font-size:20px}p{line-height:1.5;margin:8px 0}.eyebrow{color:var(--yellow);font-size:11px;font-weight:bold;letter-spacing:1.4px}.hint,.muted{font-size:12px;color:#b6c4d7}.note{padding:12px 15px;background:#252713;border:1px solid #605b24;border-radius:8px;margin:16px 0}.toolbar,.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:16px 0}.panel{min-width:0;background:#152337;border:1px solid #3b4b60;border-radius:10px;padding:18px;margin:0 0 16px}legend{font-size:16px;font-weight:bold;padding:0 7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.wide{grid-column:1/-1}label{display:block;font-size:13px;font-weight:bold;margin:0 0 7px}input,textarea,select,button{font:inherit}input,textarea,select{border:1px solid #64748b;background:#0d192c;color:white;padding:10px;min-height:42px;border-radius:6px;width:100%}textarea{min-height:66px;resize:vertical;line-height:1.5}textarea::placeholder{color:#93a3b8;opacity:.75}input:focus-visible,textarea:focus-visible,select:focus-visible,button:focus-visible{outline:2px solid var(--yellow);outline-offset:3px}button{cursor:pointer;border:1px solid #64748b;border-radius:6px;padding:10px 14px;background:#142237;color:white;font-weight:bold}.primary{background:var(--yellow);color:#000;border-color:var(--yellow)}.skill{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid #344359}.skill:last-child{border:0}.skill label{margin:0}.level{width:auto;field-sizing:content;border-radius:6px 6px 0 0;background:#0d192c;color:white}.level:valid{background:var(--yellow);color:#000}.level,.level::picker(select){appearance:base-select}.level::picker(select){border:1px solid #64748b;border-radius:6px 6px 0 0;background:#0d192c;color:#fff;width:max-content;min-width:anchor-size(width)}.level option{padding:10px;color:#fff;background:#0d192c}.level option:checked,.level option:hover,.level option:focus{background:var(--yellow);color:#000}.level option::checkmark{color:inherit}#status{color:#b7f1d2;font-weight:bold}dt{color:#b6c4d7;font-size:12px;font-weight:bold;margin-top:16px}dd{margin:5px 0 0;padding-bottom:12px;border-bottom:1px solid #344359;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5}[hidden]{display:none!important}footer{font-size:12px;color:#b6c4d7}@media(max-width:600px){header>div{padding:14px 16px;flex-wrap:wrap}.brand{font-size:16px}.badge{margin-left:60px}main{padding:0 16px 25px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.panel{padding:14px}.skill{flex-wrap:wrap}.sub{font-size:12px}}\n.row-scroll{overflow-x:auto;padding:4px;margin:-4px;outline-offset:2px}.contact-grid{display:grid;grid-template-columns:1fr 1.15fr 1fr;gap:14px;min-width:660px}.availability{border:0;margin:18px 0 0;padding:0;min-width:660px}.availability legend{font-size:13px;padding:0;margin-bottom:8px}.days{display:grid;grid-template-columns:repeat(7,1fr);gap:8px}.days label{display:flex;gap:7px;align-items:center;min-height:44px;margin:0;cursor:pointer}.days input{width:18px;min-height:18px;height:18px;padding:0;accent-color:var(--yellow)}.history{margin-top:18px}.mobile-hint{display:none}@media(max-width:740px){.mobile-hint{display:block}} input,textarea,select{padding:8px 10px;border-radius:12px;min-width:0}.level,.level::picker(select){border-radius:12px}.contact-grid{min-width:0;grid-template-columns:1fr 1fr;gap:12px}.phone-field{grid-column:1/-1;max-width:320px}.availability{min-width:0;margin-top:10px}.availability legend{margin-bottom:3px}.days{gap:4px}.days label{justify-content:center;gap:5px}.interview{margin-top:8px}.history{margin-top:12px}@media(max-width:600px){.contact-grid{grid-template-columns:1fr;gap:9px}.phone-field{max-width:none}.panel{padding:12px}.days label{flex-direction:column;gap:3px;font-size:11px;min-height:48px;justify-content:center}.days{gap:0}.days input{margin:0}input,textarea,select{padding:7px 9px}.brand{overflow-wrap:anywhere}.skill{gap:8px}.level{max-width:100%}} .panel>h2{font-size:16px;margin:0 0 14px}.period{border:0;margin:10px 0 0;padding:0;display:flex;gap:22px}.period legend{font-size:13px;padding:0;margin-bottom:4px}.period label{display:flex;align-items:center;gap:7px;min-height:44px;margin:0}.period input{width:18px;height:18px;min-height:18px;padding:0;accent-color:var(--yellow)} .phone-field{width:max-content;max-width:100%;justify-self:start;display:grid;grid-template-columns:max-content}.phone-field input{width:0;min-width:100%;max-width:100%}.phone-field label{white-space:nowrap} #interviewDays .interview-day{min-width:0}#interviewDays .interview-day>label:first-child{flex-direction:column;font-size:11px;gap:3px;min-height:48px}#interviewDays .day-period{display:flex;flex-direction:row;justify-content:center;gap:3px;font-size:10px;min-height:32px;margin:0}#interviewDays .day-period input{width:13px;height:13px;min-height:13px;margin:0}#interviewDays .day-period:has(input:disabled){opacity:.5} .panel:has(#skills){padding:12px}.panel:has(#skills)>h2{margin-bottom:6px}.panel:has(#skills)>.hint{margin:0 0 5px}.skill{padding:5px 0;gap:8px}.level{position:relative;padding:5px 14px;min-height:32px;text-align:center;text-align-last:center;gap:4px}.level::picker-icon{position:absolute;right:3px;font-size:8px}.level option{padding:5px 8px;min-height:28px;text-align:center;justify-content:center}.level option::checkmark{display:none}#interviewDays .day-period{min-height:22px;gap:3px}#interviewDays .interview-day>label:first-child{min-height:42px} .level{width:142px;min-width:142px;max-width:142px;field-sizing:fixed;padding:5px 14px;text-align:center;text-align-last:center;display:inline-flex;align-items:center;justify-content:center}.level::picker-icon{position:absolute;right:4px;top:50%;transform:translateY(-50%);margin:0;font-size:8px;line-height:1}#results{padding:12px}#results h2{margin:5px 0 7px;font-size:18px}#results p{margin:5px 0;line-height:1.35}#answers{margin:8px 0}#answers dt{margin-top:7px;line-height:1.2}#answers dd{margin:2px 0 0;padding-bottom:6px;line-height:1.3}#results .actions{margin:10px 0 0;gap:7px} </style></head><body><header><div><img src=\"data:image/png;base64,\" alt=\"CMPRI\"><div><div class=\"brand\">Residence Inn by Marriott - Champaign</div><div class=\"sub\">Hawkeye Hotels - CMPRI</div></div></div></header><main><div class=\"eyebrow\">FRONT DESK · MAINTENANCE</div><h1>A quick introduction.</h1><p>Tell us about your work experience, the tasks you have done and when you are available.</p><p class=\"muted\">About 3-5 minutes · Required fields are marked *</p><p>This is a written questionnaire only. Describe your experience. No hands-on work or testing is required.</p><div class=\"note\"><strong>Preview only — for Scott & Deon</strong><br>Use fictional details. Nothing is sent or saved. Download this HTML file and open it in a browser to review.</div><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><form id=\"application\" autocomplete=\"off\"><div style=\"position:absolute;left:-9999px\" aria-hidden=\"true\"><label>Website<input id=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label></div><fieldset class=\"panel\"><h2>1. Your basic information</h2><div class=\"contact-availability\"><div class=\"contact-grid\"><div><label for=\"name\">Full name *</label><input id=\"name\" name=\"Full name\" required maxlength=\"120\"></div><div><label for=\"email\">Email address *</label><input id=\"email\" name=\"Email address\" type=\"email\" required maxlength=\"180\"></div><div class=\"phone-field\"><label for=\"phone\">Phone number (optional)</label><input id=\"phone\" name=\"Phone number\" type=\"tel\" inputmode=\"tel\" placeholder=\"(217) 555-0123\" pattern=\"\\([0-9]{3}\\) [0-9]{3}-[0-9]{4}\" title=\"Enter exactly 10 digits, for example (217) 555-0123.\"></div></div></div></fieldset><fieldset class=\"panel\"><h2>2. Choose your position</h2><label for=\"role\">Position *</label><select id=\"role\" required><option value=\"\">Choose a position</option><option value=\"front\">Front Desk</option><option value=\"maintenance\">Maintenance</option></select><p class=\"hint\">Choose a role to see a short questionnaire — about five minutes total.</p></fieldset><div id=\"roleContent\" hidden><fieldset class=\"panel\"><h2 id=\"roleHeading\">3. A little about your experience</h2><div class=\"history\"><label for=\"history\">Relevant work history or training (one line) *</label><textarea id=\"history\" name=\"Relevant work history / training\" required maxlength=\"1500\" placeholder=\"One recent role or relevant training is enough.\"></textarea></div></fieldset><fieldset class=\"panel\"><h2>Tasks you have done</h2><p class=\"hint\">Choose your level for each area. “Not done” is a valid answer.</p><div id=\"skills\"></div></fieldset><fieldset class=\"panel\"><h2 id=\"exampleHeading\">One brief repair example</h2><p class=\"hint\" id=\"exampleLimit\">Maximum 1,500 characters per example.</p><label for=\"example\">In 1-3 sentences, describe one real repair: what was wrong, what you personally did or assisted with, and the outcome. *</label><p class=\"hint\">If you have not done a repair yet, say so.</p><textarea id=\"example\" name=\"Repair example\" required maxlength=\"1500\" aria-describedby=\"exampleLimit\" placeholder=\"Box will expand as you type\"></textarea></fieldset><fieldset class=\"panel\"><h2>4. Your availability</h2><fieldset class=\"availability\"><legend>Available working days *</legend><div class=\"days\" id=\"days\"></div></fieldset></fieldset><fieldset class=\"panel\" id=\"interviewSection\"><h2>Interview days</h2><p class=\"hint\">Choose each available day, then AM, PM or both underneath. Scott will determine the exact interview time.</p><fieldset class=\"availability interview\"><legend>Interview days *</legend><div class=\"days\" id=\"interviewDays\"></div></fieldset></fieldset><div class=\"actions\"><button class=\"primary\" type=\"submit\">Review preview answers</button><button id=\"resetButton\" type=\"button\">Clear form</button></div></div></form><footer>Human review only · No scoring, ranking or hiring decisions.</footer></main><script>\nconst form=document.getElementById('application'),status=document.getElementById('status'),example=document.getElementById('example');\nconst phone=document.getElementById('phone');\nfor(const [target,group] of [['days','Available working days'],['interviewDays','Interview days']])for(const day of ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']){const label=document.createElement('label');const box=document.createElement('input');box.type='checkbox';box.name=group;box.value=day;label.append(box,day);document.getElementById(target).append(label)}\nfor(const label of [...document.querySelectorAll('#interviewDays>label')]){\n const box=label.querySelector('input'),day=box.value,col=document.createElement('div');col.className='interview-day';box.className='day-toggle';label.replaceWith(col);col.append(label);\n for(const period of ['AM','PM']){const small=document.createElement('label');small.className='day-period';const input=document.createElement('input');input.type='checkbox';input.name='Interview '+day;input.value=period;input.disabled=true;input.setAttribute('aria-label',day+' '+period);small.append(input,period);col.append(small)}\n box.addEventListener('change',()=>{for(const input of col.querySelectorAll('.day-period input')){input.disabled=!box.checked;if(!box.checked)input.checked=false}validateDays()});\n}\nconst dayBoxes=[...document.querySelectorAll('#days input')],interviewBoxes=[...document.querySelectorAll('#interviewDays .day-toggle')];\nfunction validateDays(){for(const boxes of [dayBoxes,interviewBoxes])boxes[0].setCustomValidity(boxes.some(box=>box.checked)?'':'Select at least one day.');for(const box of interviewBoxes){const periods=[...box.closest('.interview-day').querySelectorAll('.day-period input')];periods[0].setCustomValidity(box.checked&&!periods.some(p=>p.checked)?'Choose AM or PM for this day.':'')}}\ndocument.querySelectorAll('.day-period input').forEach(box=>box.addEventListener('change',validateDays));[...dayBoxes,...interviewBoxes].forEach(box=>box.addEventListener('change',validateDays));validateDays();\nphone.addEventListener('input',()=>{const raw=phone.value,digits=raw.replace(/\\D/g,''),pos=phone.selectionStart,before=raw.slice(0,pos).replace(/\\D/g,'').length;let value=digits;if(digits.length>0)value='('+digits.slice(0,3);if(digits.length>=3)value+=') ';if(digits.length>3)value+=digits.slice(3,6);if(digits.length>=6)value+='-';if(digits.length>6)value+=digits.slice(6);phone.value=value;phone.setCustomValidity(digits.length===0||digits.length===10?'':'Enter exactly 10 digits.');let cursor=0,count=0;while(cursor<value.length&&count<before){if(/\\d/.test(value[cursor]))count++;cursor++}if(pos===raw.length)cursor=value.length;phone.setSelectionRange(cursor,cursor)});\nfunction expand(){example.value=example.value.slice(0,1500);example.style.height='auto';example.style.height=example.scrollHeight+2+'px'}example.addEventListener('input',expand);\n\nfunction reset(){form.reset();document.querySelectorAll('.day-period input').forEach(input=>{input.disabled=true;input.setCustomValidity('')});phone.setCustomValidity('');validateDays();example.style.height='';status.textContent='';document.getElementById('name').focus()}\ndocument.getElementById('resetButton').onclick=reset;\nconst role=document.getElementById('role'), content=document.getElementById('roleContent');\nconst repairLabel=document.querySelector('label[for=\"example\"]'), repairHint=repairLabel.nextElementSibling;\nconst roleDrafts={}; let previousRole='';\nconst skillsByRole={maintenance:[['hvac','HVAC maintenance'],['plumbing','Plumbing repairs'],['electrical','Electrical maintenance'],['appliances','Appliance repairs']],front:[['guests','Guest check-in / customer service'],['systems','Reservations / computer systems'],['payments','Payments / cash handling']]};\nfunction showRole(){\n if(previousRole)roleDrafts[previousRole]={example:example.value,skills:[...document.querySelectorAll('#skills select')].map(s=>s.value)};\n content.hidden=!role.value;content.querySelectorAll('input,select,textarea').forEach(el=>{if(!el.closest('#interviewDays'))el.disabled=!role.value});\n document.getElementById('skills').replaceChildren();\n if(!role.value){previousRole='';return;}\n const front=role.value==='front';\n document.getElementById('roleHeading').textContent='3. '+(front?'Front Desk':'Maintenance')+' — quick introduction';\n document.getElementById('exampleHeading').textContent=front?'One brief guest-service example':'One brief repair example';\n repairLabel.textContent=front?'In 1–3 sentences: a guest arrives upset because their room is not ready while the phone rings. What would you do first, and when would you ask for help? *':'In 1-3 sentences, describe one real repair: what was wrong, what you personally did or assisted with, and the outcome. *';\n repairHint.textContent=front?'A practical answer is enough. Hotel experience is not required.':'If you have not done a repair yet, say so.';\n document.querySelector('#interviewSection>.hint').textContent=front?'Choose each available day, then AM, PM or both underneath. Deon will determine the exact interview time.':'Choose each available day, then AM, PM or both underneath. Scott will determine the exact interview time.';\n for(const [key,label] of skillsByRole[role.value]){const row=document.createElement('div');row.className='skill';row.innerHTML=`<label for=\"${key}\">${label} *</label><select class=\"level\" id=\"${key}\" name=\"${label}\" required><option value=\"\">Choose your level</option><option value=\"Personally performed\">Perform</option><option>Assisted</option><option>Not done</option></select>`;document.getElementById('skills').append(row)}\n const draft=roleDrafts[role.value];example.value=draft?.example||'';document.querySelectorAll('#skills select').forEach((s,i)=>s.value=draft?.skills[i]||'');previousRole=role.value;expand();status.textContent='';document.getElementById('results')?.remove();\n}\nrole.addEventListener('change',showRole);showRole();\ndocument.getElementById('resetButton').onclick=()=>{previousRole='';Object.keys(roleDrafts).forEach(k=>delete roleDrafts[k]);reset();showRole();document.getElementById('results')?.remove()};\nform.addEventListener('submit',event=>{\n event.preventDefault();validateDays();if(!form.reportValidity())return;\n document.getElementById('results')?.remove();const results=document.createElement('section');results.id='results';results.className='panel';results.tabIndex=-1;\n const heading=document.createElement('h2');heading.textContent='Preview complete — nothing submitted';results.append(heading);\n const note=document.createElement('p');note.textContent='This review stays in this browser tab only. No application was sent to CMPRI.';results.append(note);\n const dl=document.createElement('dl');const entries=[['Position',role.options[role.selectedIndex].text],...new FormData(form).entries()];\n for(const [key,value] of entries){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=value;dl.append(dt,dd)}results.append(dl);form.after(results);status.textContent='Preview ready. Nothing sent or saved.';results.focus();\n});\n</script></body></html>";
